#include "KS/SRC/linear_anim_shared.h"

#define assert(condition) ((void)0)

__asm__(
    ".equ interpolate__Ct10linear_key1Z10quaternion"
    "RCt10linear_key1Z10quaternionf, 0x001133A8"
);

template <>
void key_anim<
    quaternion,
    linear_key<quaternion>,
    linear_track<quaternion>
>::get_value(float t, quaternion* dest) const
{
    assert( track!=NULL && dest!=NULL );
    linear_track<quaternion>::iterator i0 = track->m_keys;
    linear_track<quaternion>::iterator i1 = i0;
    linear_track<quaternion>::iterator i_end = (track->m_keys + track->num_keys);
    ++i1;
    while ( i1!=i_end && t>=(*i1).get_time() )
    {
      ++i0;
      ++i1;
    }
    const linear_key<quaternion>& k0 = *i0;
    const linear_key<quaternion>& k1 = *i1;
    if ( t<k0.get_time() || i1==i_end )
    {
      // off the front or back of the track
      *dest = k0.get_value();
    }
    else
    {
      // in the track;
      // interpolate between current key and the next
      *dest = k0.get_value( t, k1 );
    }
}

#undef assert
